package dev.arabicgames.phone;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicBoolean;import java.time.Duration;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class FrameLeaseRecoveryTest {
 @Test public void changingReadingReleasesOldFrameWithoutUnloadingModel(){var s=Robolectric.buildService(CaptureService.class).create().get();try{CaptureService.current=s;ReflectionHelpers.setField(s,"ready",true);ReflectionHelpers.setField(s,"epoch",3);AtomicBoolean busy=ReflectionHelpers.getField(s,"busy");busy.set(true);CaptureService.readingChanged();assertFalse(busy.get());assertTrue((Boolean)ReflectionHelpers.getField(s,"ready"));busy.set(true);ReflectionHelpers.callInstanceMethod(s,"releaseFrame",ReflectionHelpers.ClassParameter.from(int.class,3));assertTrue(busy.get());}finally{CaptureService.current=null;}}
 @Test public void hungFrameLeaseRecoversAndRejectsOldCompletion(){var s=Robolectric.buildService(CaptureService.class).create().get();try{ReflectionHelpers.setField(s,"epoch",7);assertTrue((Boolean)ReflectionHelpers.callInstanceMethod(s,"beginFrame"));Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(Duration.ofSeconds(15));AtomicBoolean busy=ReflectionHelpers.getField(s,"busy");assertFalse(busy.get());assertEquals(8,(int)ReflectionHelpers.getField(s,"epoch"));assertTrue((Boolean)ReflectionHelpers.callInstanceMethod(s,"beginFrame"));ReflectionHelpers.callInstanceMethod(s,"releaseFrame",ReflectionHelpers.ClassParameter.from(int.class,7));assertTrue(busy.get());}finally{CaptureService.current=null;((android.os.Handler)ReflectionHelpers.getField(s,"ui")).removeCallbacksAndMessages(null);}}
}
